# Load the new demo pairs that should have arrived
import os
import re

session_dir = os.environ.get('RLM_SESSION_DIR', '')
sessions_file = os.path.join(session_dir, '..', 'sessions', os.path.basename(session_dir) + '.jsonl')

print(f"Reading sessions file: {sessions_file}")

try:
    with open(sessions_file, 'r') as f:
        content = f.read()

    G = {}
    for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = match[1], int(match[2]), int(match[3])

        # Get the grid rows
        start = match.end()
        text = content[start:start+h]
        rows = text.split('\n')

        if k not in G and len(rows) == h and all(rows[i].replace(' +', '').replace('+', '').strip() for i in range(h)):
            grid = []
            for i, row_str in enumerate(rows):
                if row_str.strip() and not row_str.strip().startswith('+'):
                    grid.append([int(x) for x in row_str.split() if x.isdigit()])
                elif row_str.strip() and '+ ' in row_str:
                    # This is a separator row between input/output
                    continue
            if grid:
                G[k] = grid

    print("Grids collected:")
    for k, grid in sorted(G.items()):
        print(f"\n{k}: {len(grid)}x{len(grid[0]) if grid else 0}")
        print(f"Shape: {len(grid)} rows")
    print("\nGrill load complete")

except Exception as e:
    print(f"Error: {e}")

